using System;using UnityEngine;using UnityEditor;using RoadGunner;using RoadGunner.Editor;
public static class FinishWastelandLabels {public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Stop first");var l=RoadGunnerLevelAuthoring.Current;foreach(var t in RoadGunnerLevelAuthoring.InScene<TextMesh>()){float target=t.text=="AUTO REPAIR"?6.4f:2.4f;float width=t.GetComponent<Renderer>().localBounds.size.x;t.characterSize*=target/width;t.transform.localRotation=Quaternion.identity;if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.transform);}}foreach(var text in RoadGunnerLevelAuthoring.InScene<UnityEngine.UI.Text>())if(text.text.Contains("GREENWOOD"))text.text=text.text.Replace("GREENWOOD","RUST FRONTIER");var w=UnityEngine.Object.FindAnyObjectByType<RepairWorkshop>();w.repairingLabel.rectTransform.anchoredPosition=l.session.hud.healthText.rectTransform.anchoredPosition+new Vector2(-210,0);w.repairingLabel.rectTransform.sizeDelta=new Vector2(180,32);w.repairingLabel.fontSize=20;w.repairingLabel.alignment=TextAnchor.MiddleRight;RoadGunnerLevelAuthoring.Save(l,false);return "Readable front-facing signs; repair indicator beside HP; wasteland sector title.";}}
